'use strict';

const fs = require('fs');

// Optional invalidation callback — set by cache.js to avoid circular imports.
let _cacheInvalidator = null;
function setCacheInvalidator(fn) { _cacheInvalidator = fn; }

function atomicWriteJson(filePath, data) {
  const tmp = filePath + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf-8');
  fs.renameSync(tmp, filePath);
}

function atomicWriteText(filePath, text) {
  const tmp = filePath + '.tmp';
  fs.writeFileSync(tmp, text, 'utf-8');
  fs.renameSync(tmp, filePath);
  // Invalidate agent cache on any write whose path is inside an agents dir.
  // Cheap test — resolves the worst bug (stale cache after edit) for free.
  if (_cacheInvalidator && /\/agents\/[^/]+\.md$/.test(filePath)) {
    _cacheInvalidator(filePath);
  }
}

function readFileSafe(filePath) {
  try {
    if (fs.existsSync(filePath)) return fs.readFileSync(filePath, 'utf-8');
  } catch {}
  return null;
}

function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

module.exports = { atomicWriteJson, atomicWriteText, readFileSafe, ensureDir, setCacheInvalidator };

'use strict';

const fs = require('fs');
const path = require('path');
const matter = require('gray-matter');
const atomicIo = require('./atomicIo');

// ── Agent cache ─────────────────────────────────────────────────────────────
// Disk reads are the largest per-request cost for agent endpoints. We keep two
// in-process maps keyed by absolute path, invalidated by mtime. The PUT handler
// clears the corresponding entry after an atomic write. This is a single-process
// cache — if the server goes multi-process in future, move to Redis or similar.
const _agentCacheFull = new Map();
const _agentCacheMeta = new Map();

function _invalidateAgentCache(filePath) {
  _agentCacheFull.delete(filePath);
  _agentCacheMeta.delete(filePath);
}

// Register with atomicIo so that atomicWriteText auto-invalidates on agent writes.
atomicIo.setCacheInvalidator(_invalidateAgentCache);

function parseAgent(filePath) {
  try {
    const stats = fs.statSync(filePath);
    const hit = _agentCacheFull.get(filePath);
    if (hit && hit.mtimeMs === stats.mtimeMs) return hit.parsed;

    const content = fs.readFileSync(filePath, 'utf-8');
    const { data, content: body } = matter(content);
    const parsed = {
      filename: path.basename(filePath, '.md'),
      path: filePath,
      frontmatter: data,
      name: data.name || path.basename(filePath, '.md'),
      description: data.description || '',
      model: data.model || '',
      tools: data.tools || '',
      body: body.trim(),
      raw: content,
      updatedAt: stats.mtime.toISOString(),
    };
    _agentCacheFull.set(filePath, { mtimeMs: stats.mtimeMs, parsed });
    return parsed;
  } catch (e) {
    return null;
  }
}

// Meta-only parse: reads just enough to extract frontmatter + body line count.
// Used by list endpoints so we never ship full bodies for a 30-item list.
function parseAgentMeta(filePath) {
  try {
    const stats = fs.statSync(filePath);
    const hit = _agentCacheMeta.get(filePath);
    if (hit && hit.mtimeMs === stats.mtimeMs) return hit.meta;

    // Read until we've consumed the second '---' line; cheaper than reading the
    // whole body only to throw it away. For files without frontmatter, fall
    // back to a full read via parseAgent (rare).
    const fd = fs.openSync(filePath, 'r');
    const buf = Buffer.alloc(64 * 1024);
    let collected = '';
    let bytesRead = 0;
    let pos = 0;
    let frontmatterEnd = -1;
    const FM_RE = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/;
    try {
      while (frontmatterEnd < 0) {
        const n = fs.readSync(fd, buf, 0, buf.length, pos);
        if (n === 0) break;
        collected += buf.slice(0, n).toString('utf-8');
        bytesRead += n;
        pos += n;
        const m = collected.match(FM_RE);
        if (m) frontmatterEnd = m[0].length;
        if (bytesRead > 256 * 1024 && frontmatterEnd < 0) break; // safety cap
      }
    } finally {
      fs.closeSync(fd);
    }

    let data = {};
    if (frontmatterEnd > 0) {
      const parsed = matter(collected.slice(0, frontmatterEnd + 1024)); // buffer margin
      data = parsed.data || {};
    } else {
      // Fallback: full parse, rare case
      const full = parseAgent(filePath);
      if (!full) return null;
      return {
        filename: full.filename,
        path: full.path,
        frontmatter: full.frontmatter,
        name: full.name,
        description: full.description,
        model: full.model,
        tools: full.tools,
        bodyLines: full.body.split('\n').length,
        bodyChars: full.body.length,
        updatedAt: full.updatedAt,
      };
    }

    // Compute body size cheaply from disk via stat + frontmatter length
    const totalSize = stats.size;
    const bodyChars = Math.max(0, totalSize - frontmatterEnd);

    const meta = {
      filename: path.basename(filePath, '.md'),
      path: filePath,
      frontmatter: data,
      name: data.name || path.basename(filePath, '.md'),
      description: data.description || '',
      model: data.model || '',
      tools: data.tools || '',
      bodyLines: null, // deferred — callers that need line count use parseAgent
      bodyChars,
      updatedAt: stats.mtime.toISOString(),
    };
    _agentCacheMeta.set(filePath, { mtimeMs: stats.mtimeMs, meta });
    return meta;
  } catch (e) {
    return null;
  }
}

function listAgents(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => parseAgent(path.join(dir, f)))
      .filter(Boolean);
  } catch {
    return [];
  }
}

// Meta-only variant — same ordering, same filter, just no body.
function listAgentsMeta(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => parseAgentMeta(path.join(dir, f)))
      .filter(Boolean);
  } catch {
    return [];
  }
}

module.exports = {
  _agentCacheFull,
  _agentCacheMeta,
  _invalidateAgentCache,
  parseAgent,
  parseAgentMeta,
  listAgents,
  listAgentsMeta,
};

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const db = require('../db');

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');

function loadConfig() {
  const raw = db.loadConfig();
  if (!raw || typeof raw !== 'object') return { projectDirs: [] };
  if (!Array.isArray(raw.projectDirs)) raw.projectDirs = [];
  raw.projectDirs = raw.projectDirs.filter(d => typeof d === 'string');
  return raw;
}

function isValidName(name) {
  return /^[a-zA-Z0-9_-]+$/.test(name) && !name.includes('..');
}

function validateName(req, res, next) {
  if (!isValidName(req.params.name)) {
    return res.status(400).json({ error: 'Invalid name. Only letters, numbers, hyphens and underscores allowed.' });
  }
  next();
}

function resolveProjectPath(id) {
  try {
    const decoded = Buffer.from(id, 'base64url').toString();
    // Prevent path traversal: resolve and check for .. sequences
    const resolved = path.resolve(decoded);
    if (resolved.includes('..') || decoded.includes('\0')) return null;
    return resolved;
  } catch {
    return null;
  }
}

function validateProjectId(req, res, next) {
  const projectPath = resolveProjectPath(req.params.id);
  if (!projectPath) {
    return res.status(400).json({ error: 'Invalid project ID' });
  }
  // Verify it's within allowed project directories
  const config = loadConfig();
  const allowedRoots = [
    CLAUDE_DIR,
    ...config.projectDirs.map(d => path.resolve(d.replace(/^~/, HOME))),
  ];
  const isAllowed = allowedRoots.some(root =>
    projectPath === root || projectPath.startsWith(root + path.sep)
  );
  if (!isAllowed) {
    return res.status(403).json({ error: 'Project outside allowed directories' });
  }
  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
    return res.status(404).json({ error: 'Project directory not found' });
  }
  req.projectPath = projectPath;
  next();
}

module.exports = { isValidName, validateName, resolveProjectPath, validateProjectId };

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const { readFileSafe } = require('./atomicIo');
const { listAgents } = require('./cache');

const HOME = os.homedir();

function listMdFiles(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => {
        const filePath = path.join(dir, f);
        const content = readFileSafe(filePath);
        const stats = fs.statSync(filePath);
        return {
          name: f.replace('.md', ''),
          content: content || '',
          path: filePath,
          updatedAt: stats.mtime.toISOString(),
        };
      });
  } catch {
    return [];
  }
}

function discoverProjects(dirs) {
  const projects = [];
  for (const dir of dirs) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
          projects.push({
            id: Buffer.from(projectPath).toString('base64url'),
            name: entry.name,
            path: projectPath,
            displayPath: projectPath.replace(HOME, '~'),
            hasClaudeDir,
            hasClaudeMd,
            agentCount: agents.length,
            commandCount: commands.length,
            ruleCount: rules.length,
            agents,
            commands: commands.map(c => c.name),
            rules: rules.map(r => r.name),
          });
        }
      }
    } catch {}
  }
  return projects;
}

module.exports = { discoverProjects, listMdFiles };

'use strict';

// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

// Level-based grouping for parallel execution
function topoLevels(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source] = adj[e.source] || [];
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const levels = [];
  let queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  while (queue.length) {
    levels.push([...queue]);
    const nextQueue = [];
    for (const id of queue) {
      for (const next of (adj[id] || [])) {
        inDegree[next]--;
        if (inDegree[next] === 0) nextQueue.push(next);
      }
    }
    queue = nextQueue;
  }
  return levels;
}

module.exports = { topoSort, topoLevels };

'use strict';

function computeLineDiff(before, after) {
  const oldLines = (before || '').split('\n');
  const newLines = (after || '').split('\n');
  const hunks = [];
  const maxLen = Math.max(oldLines.length, newLines.length);
  let i = 0;
  while (i < maxLen) {
    // Skip identical lines
    if (i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i]) { i++; continue; }
    // Start of a changed region
    const hunkStart = i;
    const removed = [];
    const added = [];
    // Collect contiguous changed lines (simple sequential diff)
    while (i < maxLen && !(i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i])) {
      if (i < oldLines.length && (i >= newLines.length || oldLines[i] !== newLines[i])) {
        removed.push(oldLines[i]);
      }
      if (i < newLines.length && (i >= oldLines.length || oldLines[i] !== newLines[i])) {
        added.push(newLines[i]);
      }
      i++;
    }
    if (removed.length || added.length) {
      hunks.push({ line: hunkStart + 1, removed, added });
    }
  }
  return hunks;
}

module.exports = { computeLineDiff };

'use strict';

const ALLOWED_ORIGINS = new Set([
  'http://localhost:3847',
  'http://localhost:5173',   // Vite dev
  'http://localhost:3000',
  'http://localhost:8080',
  'http://127.0.0.1:3847',
  'http://127.0.0.1:5173',
  'http://127.0.0.1:3000',
  'http://127.0.0.1:8080',
]);

function cors(req, res, next) {
  const origin = req.headers.origin;
  if (origin && ALLOWED_ORIGINS.has(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  } else if (!origin) {
    // Same-origin or non-browser client — no CORS header needed
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
}

module.exports = cors;

'use strict';

const rateLimitMap = new Map();
const RATE_LIMIT_WINDOW = 60_000; // 1 minute
const RATE_LIMITS = {
  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
  write: 60,   // file writes, creates, deletes — 60/min
  read: 200,   // reads, listings — 200/min
};

function rateLimit(tier) {
  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
  return (req, res, next) => {
    const key = `${tier}:${req.ip}`;
    const now = Date.now();
    let entry = rateLimitMap.get(key);
    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
      entry = { start: now, count: 0 };
      rateLimitMap.set(key, entry);
    }
    entry.count++;
    if (entry.count > max) {
      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
    }
    next();
  };
}

// Cleanup stale entries every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of rateLimitMap) {
    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
  }
}, 300_000);

module.exports = { rateLimit, RATE_LIMITS };

